<?php use App\Http\Labels; ?>
<div class="grid g2"><div class="card"><h2><?= e($i['incident_no']) ?> <?= Labels::emergency($i['status'])->html ?></h2>
<table><tr><th>السائق</th><td><?= e($i['driver_name']) ?> <span class="mut"><?= e($i['phone']) ?></span></td></tr><tr><th>النوع</th><td><?= e($i['type_name'] ?? 'غير محدد') ?></td></tr>
<tr><th>وقت الضغط (جهاز السائق)</th><td><?= e(Labels::dt($i['created_at_client'])) ?></td></tr><tr><th>وقت الوصول للخادم</th><td><?= e(Labels::dt($i['received_at'])) ?> (<?= e($i['channel'] === 'sms_fallback' ? 'عبر SMS احتياطي' : 'عبر الإنترنت') ?>)</td></tr>
<tr><th>الموقع</th><td><?= $i['lat'] !== null ? e($i['lat'] . ', ' . $i['lon']) . ($i['location_is_last_known'] ? ' <span class="badge b-warn">آخر موقع معروف — قديم</span> ' . e(Labels::dt($i['location_at'])) : ' · دقة ' . e($i['accuracy_m']) . ' م') : 'غير متوفر' ?></td></tr>
<tr><th>المركبة</th><td><?= e($i['plate_no'] ?? '—') ?></td></tr><tr><th>ملاحظات السائق</th><td><?= e($i['notes']) ?></td></tr>
<tr><th>الاستلام</th><td><?= $i['acknowledged_at'] ? e(Labels::dt($i['acknowledged_at'])) . ' — ' . e($i['ack_name']) : '<span class="err">لم يُستلم</span> · مستوى التصعيد ' . (int)$i['escalation_level'] ?></td></tr>
<tr><th>مسؤول المتابعة</th><td><?= e($i['followup_name'] ?? '—') ?></td></tr><?php if ($i['close_reason']): ?><tr><th>سبب الإغلاق</th><td><?= e($i['close_reason']) ?></td></tr><?php endif; ?></table>
<?php if ($i['lat'] !== null): ?><div id="map" class="map" style="height:280px;margin-top:12px"></div><?php endif; ?>
<?php foreach ($attachments as $a): ?><p><a href="/api/v1/admin/attachments/<?= (int)$a['id'] ?>/file" target="_blank" rel="noopener">مرفق #<?= (int)$a['id'] ?></a></p><?php endforeach; ?></div>
<div class="card"><h2>الإجراءات</h2>
<?php if (!in_array($i['status'], ['closed','false_alarm'], true)): ?>
<div class="row"><?php if ($i['status'] === 'new' && $can['ack']): ?><form method="post" action="/emergencies/<?= (int)$i['id'] ?>/acknowledge"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><button class="btn">تأكيد الاستلام</button></form><?php endif; ?>
<?php if ($can['ack'] && $i['status'] !== 'new'): foreach (['in_progress' => 'قيد المعالجة', 'awaiting_update' => 'بانتظار تحديث', 'resolved' => 'تمت المعالجة'] as $s => $l): if ($s !== $i['status']): ?><form method="post" action="/emergencies/<?= (int)$i['id'] ?>/status"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><input type="hidden" name="status" value="<?= $s ?>"><button class="btn sec sm"><?= $l ?></button></form><?php endif; endforeach; endif; ?></div>
<?php if ($can['assign']): ?><form method="post" action="/emergencies/<?= (int)$i['id'] ?>/assign" class="row" style="margin-top:10px"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><select name="assignee_user_id"><?php foreach ($assignees as $a): ?><option value="<?= (int)$a['id'] ?>"><?= e($a['full_name']) ?></option><?php endforeach; ?></select><button class="btn sec">تعيين مسؤول متابعة</button></form><?php endif; ?>
<?php if ($can['ack']): ?><form method="post" action="/emergencies/<?= (int)$i['id'] ?>/actions" class="f" style="margin-top:12px"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><div><label>نوع الإجراء</label><select name="type"><option value="call">اتصال</option><option value="message">رسالة</option><option value="dispatch">إرسال دعم</option><option value="note">ملاحظة</option><option value="other">أخرى</option></select></div><div class="w"><label>التفاصيل</label><input name="details" required></div><div class="w"><button class="btn sec">تسجيل إجراء</button></div></form>
<form method="post" action="/emergencies/<?= (int)$i['id'] ?>/updates" class="row" style="margin-top:10px"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><input name="message" placeholder="تحديث يظهر للسائق في تطبيقه" required style="flex:1"><button class="btn sec">إرسال تحديث للسائق</button></form><?php endif; ?>
<?php if ($can['close']): ?><form method="post" action="/emergencies/<?= (int)$i['id'] ?>/close" class="row" style="margin-top:14px" data-confirm="تأكيد إغلاق البلاغ؟"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><input name="reason" placeholder="سبب الإغلاق (إلزامي)" required style="flex:1"><label class="row" style="margin:0"><input type="checkbox" name="false_alarm" value="1" style="width:auto;min-height:0"> إنذار خاطئ</label><button class="btn bad">إغلاق</button></form><?php endif; ?>
<?php endif; ?>
<h2 style="margin-top:18px">سجل الإجراءات</h2><ul class="tl"><?php foreach ($actions as $a): ?><li><b><?= e($a['action_type']) ?></b> — <?= e($a['details']) ?><br><span class="mut"><?= e(Labels::dt($a['created_at'])) ?> · <?= e($a['actor_name'] ?? 'النظام') ?></span></li><?php endforeach; ?></ul>
<?php if ($escalations): ?><h2>التصعيد</h2><ul class="tl"><?php foreach ($escalations as $s): ?><li>المستوى <?= (int)$s['level'] ?> — <?= e($s['reason']) ?> <span class="mut"><?= e(Labels::dt($s['escalated_at'])) ?></span></li><?php endforeach; ?></ul><?php endif; ?></div></div>
